using Test, GravitationalWaveforms, DelimitedFiles

# SEOBNRv5PHM frequency domain (hphc: FFT of the time-domain model on the frequency grid's time grid) against pyseobnr
# 0.3.7 GenerateWaveform TD polarizations (ODE rtol 1e-11, converged) transformed with the same turn-on (test/data/phm_fd, generated by
# scripts/pyseobnr_phm_fd_reference.py): physical units and LAL conventions, no time or phase maximization.

const _PHM_FD_DIR = joinpath(@__DIR__, "data", "phm_fd")

function _phmfd_header(f)
    d = Dict{String,Any}()
    for m in eachmatch(r"(\w+)=(\[[^\]]*\]|[-0-9.eE+]+)", readline(f))
        d[m[1]] = m[2][1] == '[' ? parse.(Float64, split(m[2][2:end-1], ",")) : parse(Float64, m[2])
    end
    return d
end
_phmfd_psd(f) = (x = f / 215; 1e-49 * (x^(-4.14) - 5 * x^(-2) + 111 * (1 - x^2 + 0.5 * x^4) / (1 + 0.5 * x^2)))

@testset "SEOBNRv5PHM frequency domain vs pyseobnr GenerateWaveform ($tag)" for tag in ("a", "b")
    f = joinpath(_PHM_FD_DIR, "pyseobnr037_phmfd_$(tag).csv")
    h = _phmfd_header(f)
    d = readdlm(f, ',', Float64; comments = true)
    freqs = d[:, 1]
    ref_p = complex.(d[:, 2], d[:, 3])
    ref_c = complex.(d[:, 4], d[:, 5])
    hp, hc = hphc(SEOBNRv5PHM(), freqs, h["m1"], h["m2"], h["chi1"], h["chi2"], h["dist"] / 1000, h["incl"], h["phi_ref"])
    sel = freqs .>= 25
    w = 1 ./ _phmfd_psd.(freqs[sel])
    ip(a, b) = real(sum(conj.(a[sel]) .* b[sel] .* w))
    for (A, B) in ((ref_p, hp), (ref_c, hc))
        @test ip(A, B) / sqrt(ip(A, A) * ip(B, B)) > 1 - 5e-4
        @test abs(sqrt(ip(B, B) / ip(A, A)) - 1) < 2e-3
    end
end
